import operator
import re
import sys
import threading

_TOKEN_RE = re.compile(
    r"\s*(?:([A-Z][1-9][0-9]?)(?![0-9])|([A-Z]+)|([0-9]+)|(<>|<=|>=|[=<>+\-*/(),:]))"
)
_COMPARE = {
    "=": operator.eq,
    "<>": operator.ne,
    "<": operator.lt,
    "<=": operator.le,
    ">": operator.gt,
    ">=": operator.ge,
}
_DIV0 = "#DIV/0!"
_CYCLE = "#CYCLE!"


def _is_err(value):
    return isinstance(value, str)


def _tokenize(text):
    tokens = []
    text = text.rstrip()
    pos = 0
    while pos < len(text):
        m = _TOKEN_RE.match(text, pos)
        pos = m.end()
        if m.group(1):
            tokens.append(("cell", m.group(1)))
        elif m.group(2):
            tokens.append(("word", m.group(2)))
        elif m.group(3):
            tokens.append(("num", int(m.group(3))))
        else:
            tokens.append(("op", m.group(4)))
    return tokens


def _parse(tokens):
    pos = 0

    def peek(offset=0):
        i = pos + offset
        return tokens[i] if i < len(tokens) else (None, None)

    def take():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def is_op(value, offset=0):
        return peek(offset) == ("op", value)

    def expect(value):
        if not is_op(value):
            raise ValueError("expected " + value)
        take()

    def formula():
        node = term()
        while is_op("+") or is_op("-"):
            op = take()[1]
            node = ("bin", op, node, term())
        return node

    def term():
        node = unary()
        while is_op("*") or is_op("/"):
            op = take()[1]
            node = ("bin", op, node, unary())
        return node

    def unary():
        if is_op("-"):
            take()
            return ("neg", unary())
        return atom()

    def arg():
        if peek()[0] == "cell" and is_op(":", 1) and peek(2)[0] == "cell":
            a = take()[1]
            take()
            b = take()[1]
            return ("range", a, b)
        return formula()

    def atom():
        kind, val = take()
        if kind == "num":
            return ("num", val)
        if kind == "cell":
            return ("ref", val)
        if kind == "op" and val == "(":
            node = formula()
            expect(")")
            return node
        if kind == "word":
            expect("(")
            if val == "IF":
                left = formula()
                op = take()[1]
                right = formula()
                expect(",")
                then = formula()
                expect(",")
                other = formula()
                expect(")")
                return ("if", left, op, right, then, other)
            args = [arg()]
            while is_op(","):
                take()
                args.append(arg())
            expect(")")
            return ("call", val, args)
        raise ValueError("unexpected token")

    return formula()


def _solve(cells):
    values = {}
    in_progress = set()
    positions = sorted(
        ((int(n[1:]), ord(n[0]) - ord("A"), n) for n in cells)
    )

    def range_names(a, b):
        r1, c1 = int(a[1:]), ord(a[0]) - ord("A")
        r2, c2 = int(b[1:]), ord(b[0]) - ord("A")
        lo_r, hi_r = min(r1, r2), max(r1, r2)
        lo_c, hi_c = min(c1, c2), max(c1, c2)
        return [
            n for r, c, n in positions
            if lo_r <= r <= hi_r and lo_c <= c <= hi_c
        ]

    def cell_value(name):
        if name not in cells:
            return 0
        if name in values:
            return values[name]
        if name in in_progress:
            return _CYCLE
        in_progress.add(name)
        content = cells[name].strip()
        if content.startswith("="):
            result = evaluate(_parse(_tokenize(content[1:])))
        else:
            result = int(content)
        in_progress.discard(name)
        values[name] = result
        return result

    def evaluate(node):
        tag = node[0]
        if tag == "num":
            return node[1]
        if tag == "ref":
            return cell_value(node[1])
        if tag == "neg":
            v = evaluate(node[1])
            return v if _is_err(v) else -v
        if tag == "bin":
            left = evaluate(node[2])
            if _is_err(left):
                return left
            right = evaluate(node[3])
            if _is_err(right):
                return right
            op = node[1]
            if op == "+":
                return left + right
            if op == "-":
                return left - right
            if op == "*":
                return left * right
            if right == 0:
                return _DIV0
            q = abs(left) // abs(right)
            return q if (left < 0) == (right < 0) else -q
        if tag == "if":
            left = evaluate(node[1])
            if _is_err(left):
                return left
            right = evaluate(node[3])
            if _is_err(right):
                return right
            if _COMPARE[node[2]](left, right):
                return evaluate(node[4])
            return evaluate(node[5])
        name, args = node[1], node[2]
        vals = []
        for a in args:
            if a[0] == "range":
                for n in range_names(a[1], a[2]):
                    v = cell_value(n)
                    if _is_err(v):
                        return v
                    vals.append(v)
            else:
                v = evaluate(a)
                if _is_err(v):
                    return v
                vals.append(v)
        if name == "SUM":
            return sum(vals)
        if not vals:
            return 0
        return min(vals) if name == "MIN" else max(vals)

    for _, _, name in positions:
        cell_value(name)
    return {name: values[name] for name in cells}


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    out = {}

    def work():
        out.update(_solve(cells))

    old_limit = sys.getrecursionlimit()
    sys.setrecursionlimit(1000000)
    threading.stack_size(256 * 1024 * 1024)
    t = threading.Thread(target=work)
    t.start()
    t.join()
    threading.stack_size(0)
    sys.setrecursionlimit(old_limit)
    return out
